"use client";
// New-mod flow (r39): game -> version -> server, cost first (tokens the build may hold, from the account's own
// reserve table; never a price we made up), templates gallery, then the prompt. Creating posts to the same build API
// the studio uses (it re-checks plan, model and tokens server side) and lands on the new project's page.
import { useEffect, useMemo, useState } from "react";
import type { CyrusGame } from "@/lib/cyrus/games";
import type { CyrusModelId } from "@/lib/cyrus/models";
import { CYRUS_MODELS } from "@/lib/cyrus/models";
import type { PlanResponse } from "@/lib/cyrus/planner/run";
import { VersionPicker, recallVersion } from "@/components/cyrus/prompt/VersionPicker";
import { estimate } from "@/lib/cyrus/estimate";
import { PLAN_WARNING_COPY } from "@/lib/cyrus/limits/plan";
import { CYRUS_TEMPLATES, CYRUS_TEMPLATE_CATS, CYRUS_STUDIO_LABEL, NEW_MOD_EXAMPLES, templatePlanLabel } from "@/lib/cyrus/templates";
import type { MbServer } from "@/lib/cyrus/builder/types";
import { MSG, TIPS } from "@/lib/cyrus/content/copy";
import { cyrusTokens } from "@/components/cyrus-tokens/store";

/** v8 capability manifest per `${game}@${version}` (computed on the server): template ids, example prompts, studios shown, why-not lines. */
export type GameFitView = { templates: string[]; examples: string[]; studios: string[]; whyNot: { title: string; reason: string }[] };

export type CostInfo = { active: boolean; enforce: boolean; available: number; models: CyrusModelId[]; reserve: Record<string, Record<string, [number, number]>> | null };

const n = (x: number) => x.toLocaleString("en-US");

export function NewModFlow({ games, servers, cost, projectBase, studioHref, fits }: { games: CyrusGame[]; servers: MbServer[]; cost: CostInfo; projectBase: string; studioHref: string; fits?: Record<string, GameFitView> }) {
  const live = games.filter((g) => g.status === "live");
  const [gameId, setGameId] = useState(live[0]?.id ?? "");
  const game = games.find((g) => g.id === gameId) ?? live[0];
  const [version, setVersion] = useState(game?.defaultVersion ?? game?.versions[0] ?? "");
  // Live-test fix (E): the last version picked comes back (when Cyrus can still build it for this game)
  useEffect(() => { const v = recallVersion(); if (v && game?.versions.includes(v)) setVersion(v); }, [game?.id]); // eslint-disable-line react-hooks/exhaustive-deps
  const [serverId, setServerId] = useState<string>("");
  const [model, setModel] = useState<CyrusModelId>(cost.active && cost.models.length ? (cost.models.includes("saka") ? "saka" : cost.models[0]) : "saka");
  const [cat, setCat] = useState<(typeof CYRUS_TEMPLATE_CATS)[number]>("All");
  const [prompt, setPrompt] = useState("");
  const [picked, setPicked] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const est = useMemo(() => (prompt.trim() ? estimate(prompt, model) : null), [prompt, model]);
  const table = cost.active && cost.reserve ? cost.reserve[model] : null;
  const range = est && table ? table[est.complexity] : null;
  const span = table ? [Math.min(...Object.values(table).map((r) => r[0])), Math.max(...Object.values(table).map((r) => r[1]))] : null;
  const locked = cost.active && cost.enforce && !cost.models.includes(model);
  const short = !!range && cost.enforce && cost.available < range[0];
  const fit = fits?.[`${game?.id}@${version}`];
  const templates = CYRUS_TEMPLATES.filter((t) => (cat === "All" || t.cat === cat) && (!fit || fit.templates.includes(t.id)));
  // v8: example prompts for the chosen game + version (capability manifest); the Minecraft list when there is none
  const examples = fit?.examples.length ? fit.examples : NEW_MOD_EXAMPLES;
  const tpl = picked ? CYRUS_TEMPLATES.find((t) => t.id === picked && t.prompt === prompt) ?? null : null;
  const step = !game ? 1 : !prompt.trim() ? 3 : 4;

  // Live-test fix (F): the plan comes first (lanes, what this version cannot do, cost per model); nothing is held until
  // the second press ("Build mod", or "Continue anyway" when a needed lane cannot be built here).
  const [plan, setPlan] = useState<{ key: string; res: PlanResponse & { buildable?: boolean } } | null>(null);
  const planKey = `${prompt.trim()}\n${version}`;
  const current = plan && plan.key === planKey ? plan.res : null;
  const create = async () => {
    setBusy(true); setErr(null);
    if (!current) {
      try {
        const r = await fetch("/api/cyrus/plan", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt: prompt.trim(), mcVersion: version }) });
        const j = (await r.json().catch(() => ({}))) as PlanResponse & { error?: string };
        if (r.ok) setPlan({ key: planKey, res: j }); else setErr(j.error || MSG.buildStart(r.status));
      } catch { setErr(MSG.networkBuild); }
      setBusy(false);
      return;
    }
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt: prompt.trim(), mcVersion: version, model, assets: current.assets, plannerSource: current.planner.source, ...(current.plan.mustConfirm ? { planAck: true } : {}) }) });
      const j = (await r.json().catch(() => ({}))) as { build?: { id: string; rootBuildId: string | null }; error?: string; code?: string };
      if (r.status === 201 && j.build) { location.href = `${projectBase}/${encodeURIComponent(j.build.rootBuildId || j.build.id)}${serverId ? `?server=${encodeURIComponent(serverId)}` : ""}`; return; }
      if (cyrusTokens.handleBuildError(j)) setErr(j.error || MSG.needTokens);
      else setErr(j.error || MSG.buildStart(r.status));
    } catch { setErr(MSG.networkBuild); }
    setBusy(false);
  };

  return (
    <div className="cx-grid" style={{ alignItems: "start" }}>
      <div className="cx-s8" style={{ display: "grid", gap: 14 }}>
        <ol className="cx-steps" aria-label="Steps" style={{ listStyle: "none", padding: 0, margin: 0 }}>
          {["Game", "Version and server", "Describe", "Build"].map((s, i) => <li key={s} className="cx-step" data-on={step >= i + 1 ? "1" : "0"}><i>{i + 1}</i>{s}</li>)}
        </ol>

        <section className="cx-card" aria-labelledby="nm-game">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-game">Game</h2></div>
          <div className="cx-pick" role="radiogroup" aria-label="Game">
            {games.map((g) => (
              <button key={g.id} type="button" role="radio" aria-checked={g.id === gameId} className="cx-opt" disabled={g.status !== "live"} onClick={() => { setGameId(g.id); setVersion(g.defaultVersion ?? g.versions[0] ?? ""); }}>
                <span style={{ display: "flex", alignItems: "center", gap: 10 }}><span className={`cx-tile${g.id === gameId ? " cx-energy" : ""}`}>{g.mark}</span><span className="cx-t">{g.name}</span></span>
                <span className="cx-d">{g.status === "live" ? g.builds : "Coming soon"}</span>
              </button>
            ))}
          </div>
        </section>

        <section className="cx-card" aria-labelledby="nm-target">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-target">Version and server</h2></div>
          <div className="cx-grid">
            <div className="cx-label cx-s6">{game?.loader ?? "Server"} version
              <VersionPicker value={version} onChange={setVersion} compact label={`${game?.name ?? "Minecraft"} version`} game={game?.id ?? "minecraft"} />
            </div>
            <label className="cx-label cx-s6">Install on
              <select className="cx-select" value={serverId} onChange={(e) => setServerId(e.target.value)}>
                <option value="">No server: I will download the jar</option>
                {servers.map((s) => <option key={s.id} value={s.id} disabled={!s.compatible}>{s.name}{s.compatible ? "" : ` (${s.reason ?? "not ready"})`}</option>)}
              </select>
            </label>
          </div>
          <p className="cx-faint" style={{ margin: "10px 0 0", fontSize: 12.5 }}>{servers.length ? "You install from the project page once the build and its Test Flight finish." : "No Minecraft servers on your Nxeon account: you get a jar to install anywhere."}</p>
        </section>

        {fit ? (
          <section className="cx-card" aria-labelledby="nm-fit">
            <div className="cx-card-h"><h2 className="cx-h2" id="nm-fit">What you can make for {game?.name} {version}</h2></div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>{fit.studios.map((x) => <span key={x} className="cx-pill">{x}</span>)}</div>
            {fit.whyNot.length ? (
              <details style={{ marginTop: 12 }}><summary className="cx-muted" style={{ cursor: "pointer", fontSize: 13 }}>Why are some things not here?</summary>
                <ul className="cx-muted" style={{ fontSize: 12.5, margin: "8px 0 0", paddingLeft: 18 }}>{fit.whyNot.map((w) => <li key={w.title}><b>{w.title}:</b> {w.reason}</li>)}</ul>
              </details>
            ) : null}
          </section>
        ) : null}

        <section className="cx-card" aria-labelledby="nm-tpl">
          <div className="cx-card-h"><h2 className="cx-h2" id="nm-tpl">Start from a template</h2><span className="cx-aside">or write your own below</span></div>
          <div className="cx-seg" role="group" aria-label="Template category" style={{ marginBottom: 12 }}>
            {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" aria-pressed={c === cat} onClick={() => setCat(c)}>{c}</button>)}
          </div>
          <div className="cx-pick">
            {!templates.length ? <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>No templates for this game yet. Describe your mod below.</p> : null}
            {templates.map((t) => (
              <button key={t.id} type="button" className="cx-opt" aria-pressed={prompt === t.prompt} onClick={() => { setPrompt(t.prompt); setPicked(t.id); if (!cost.active || cost.models.includes(t.model)) setModel(t.model); }}>
                <span className="cx-eyebrow">{t.cat} · {templatePlanLabel(t)}</span><span className="cx-t">{t.title}</span><span className="cx-d">{t.blurb}</span>
              </button>
            ))}
          </div>
          {tpl ? (
