    : { active: false, enforce: false, available: 0, models: [], reserve: null };
  // v8 capability manifest per live game + version: only templates, studios and prompts that game can use
  const fits: Record<string, GameFitView> = {};
  const switches = await studioSwitches();
  for (const g of CYRUS_GAMES.filter((x) => x.status === "live")) for (const ver of g.versions) {
