    fits[`${g.id}@${ver}`] = { templates: m.templates.map((t) => t.id), examples: m.examplePrompts, studios: shownStudios(m).map((x) => STUDIO_LABEL[x.id]), whyNot: m.whyNot.map((w) => ({ title: w.title, reason: w.reason })) };
  }
  return (
    <>
      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">New mod</div>
          <h1 className="cx-h1">What should Cyrus <span className="cx-grad">build</span>?</h1>
          <p className="cx-sub">Pick where it runs and see what it costs before anything starts.</p>
        </div>
      </header>
      <NewModFlow games={CYRUS_GAMES} servers={servers} cost={cost} projectBase={v.href(P.projects)} studioHref={v.onCyrus ? "/studio" : "/dashboard/cyrus"} fits={fits} />
    </>
  );
}

