// Cyrus admin "Live" tab (2026-10-13): the maths behind the auto-refreshing feed and the bugs-and-errors groups.
// PURE and client-safe (the feed component imports the filters); unit-tested in test/cyrus-admin-live.test.ts.
// Everything works on rows the server already read from ModBuild; nothing here touches a DB or the clock unless passed in.
import { buildOutcome, type BuildOutcome } from "./metrics";

export const LIVE_POLL_MS = 5_000;
export const LIVE_WINDOW_MS = 24 * 3_600_000;
export const LIVE_MAX_ROWS = 200;

export type LiveFilter = "all" | "running" | "failed" | "succeeded" | "1h";
export const LIVE_FILTERS: { id: LiveFilter; label: string }[] = [
  { id: "all", label: "All" },
  { id: "running", label: "Running" },
  { id: "failed", label: "Failed" },
  { id: "succeeded", label: "Succeeded" },
  { id: "1h", label: "Last hour" },
];
export const isLiveFilter = (v: unknown): v is LiveFilter => LIVE_FILTERS.some((f) => f.id === v);

/** One feed line. Dates are ISO strings so the row crosses the API boundary unchanged. */
export type LiveRow = {
  id: string;
  at: string;
  /** masked account label (never the full email in the feed) */
  account: string;
  userId: string;
  /** the prompt, cut to PROMPT_CUT chars */
  prompt: string;
  /** true when the stored prompt is longer than what the row carries */
  promptCut: boolean;
  model: string;
  status: string;
  outcome: BuildOutcome;
  costUsd: number;
  /** cost is the service's running estimate (an in-progress build), not the settled figure */
  costLive: boolean;
  durationMs: number | null;
  errorCode: string | null;
  error: string | null;
  game: string;
  mcVersion: string;
};

export const PROMPT_CUT = 140;

/** "j***@gmail.com": enough to tell accounts apart, not enough to identify one. Falls back to a short id. */
export function maskEmail(email: string | null | undefined, id = ""): string {
  const e = (email ?? "").trim();
  const at = e.lastIndexOf("@");
  if (at < 1) return id ? `user ${id.slice(0, 6)}` : "unknown";
  return `${e[0]}***${e.slice(at)}`;
}

export function cutPrompt(p: string, n = PROMPT_CUT): { text: string; cut: boolean } {
  const s = p.replace(/\s+/g, " ").trim();
  return s.length > n ? { text: s.slice(0, n - 1) + "…", cut: true } : { text: s, cut: false };
}

export type LiveSource = {
  id: string; userId: string; status: string; errorCode: string | null; error: string | null; costUsd: number; durationMs: number | null;
  createdAt: Date; prompt: string; changeRequest?: string | null; mcVersion: string; model: string; game: string;
  /** running cost the build service reported (result.live.costUsd) */
  liveCostUsd?: number | null;
};

export function toLiveRow(s: LiveSource, email: string | null | undefined): LiveRow {
  const outcome = buildOutcome(s);
  const c = cutPrompt(s.changeRequest || s.prompt);
  const running = outcome === "running";
  const live = running && typeof s.liveCostUsd === "number" && Number.isFinite(s.liveCostUsd) && s.liveCostUsd > s.costUsd;
  return {
    id: s.id,
    at: s.createdAt.toISOString(),
    account: maskEmail(email, s.userId),
    userId: s.userId,
    prompt: c.text,
    promptCut: c.cut,
    model: s.model,
    status: s.status,
    outcome,
    costUsd: live ? (s.liveCostUsd as number) : s.costUsd || 0,
    costLive: live,
    durationMs: s.durationMs,
    errorCode: s.errorCode,
    error: s.error ? firstLine(s.error, 160) : null,
    game: s.game,
    mcVersion: s.mcVersion,
  };
}

export function matchLive(r: Pick<LiveRow, "outcome" | "at">, f: LiveFilter, now: Date): boolean {
  switch (f) {
    case "running": return r.outcome === "running";
    case "failed": return r.outcome === "failed" || r.outcome === "refused";
    case "succeeded": return r.outcome === "succeeded";
    case "1h": return now.getTime() - new Date(r.at).getTime() <= 3_600_000;
    default: return true;
  }
}

export function filterLive<T extends Pick<LiveRow, "outcome" | "at">>(rows: T[], f: LiveFilter, now: Date): T[] {
  return rows.filter((r) => matchLive(r, f, now));
}

export const LIVE_COUNT_KEYS = ["running", "failed", "succeeded"] as const;

// ---------------------------------------------------------------------------
// Bugs and errors
// ---------------------------------------------------------------------------

export function firstLine(s: string, max = 200): string {
  const line = s.split(/\r?\n/).map((l) => l.trim()).find(Boolean) ?? "";
  return line.length > max ? line.slice(0, max - 1) + "…" : line;
}

/** Collapse the parts of an error line that differ per build (ids, hashes, numbers, quoted names) so equal bugs group. */
export function normaliseError(s: string): string {
  return firstLine(s, 240)
    .toLowerCase()
    .replace(/\b[0-9a-f]{8,}\b/g, "#")
    .replace(/c[a-z0-9]{24}\b/g, "#")
    .replace(/(["'`]).{0,60}?\1/g, "$1…$1")
    .replace(/\d+(\.\d+)?/g, "N")
    .replace(/\s+/g, " ")
    .slice(0, 160);
}

export type ErrorSource = { id: string; userId: string; status: string; errorCode: string | null; error: string | null; errorDetail?: string | null; createdAt: Date; model?: string | null; mcVersion?: string };

export type ErrorGroup = {
  /** stable key: `${errorCode}|${normalised first line}` */
  key: string;
  errorCode: string | null;
  line: string;
  count: number;
  accounts: number;
  lastSeen: string;
  firstSeen: string;
  exampleBuildId: string;
  /** a short technical excerpt of the latest example (never a prompt, never an email) */
  detail: string;
  models: string[];
};

/** Failed builds (our side or the customer's code, NOT safety refusals and NOT cancels) grouped by code + first error line. */
export function groupErrors(rows: ErrorSource[]): ErrorGroup[] {
  const by = new Map<string, { g: ErrorGroup; users: Set<string>; latest: number; earliest: number }>();
  for (const r of rows) {
    if (buildOutcome(r) !== "failed") continue;
    const line = r.error ? firstLine(r.error) : r.errorCode ?? "(no message)";
    const key = `${r.errorCode ?? "none"}|${normaliseError(line)}`;
    const t = r.createdAt.getTime();
    const cur = by.get(key);
    if (!cur) {
      by.set(key, {
        g: { key, errorCode: r.errorCode, line, count: 1, accounts: 1, lastSeen: r.createdAt.toISOString(), firstSeen: r.createdAt.toISOString(), exampleBuildId: r.id, detail: excerpt(r.errorDetail), models: r.model ? [r.model] : [] },
        users: new Set([r.userId]), latest: t, earliest: t,
      });
      continue;
    }
    cur.g.count++;
    cur.users.add(r.userId);
    if (r.model && !cur.g.models.includes(r.model)) cur.g.models.push(r.model);
    if (t > cur.latest) { cur.latest = t; cur.g.lastSeen = r.createdAt.toISOString(); cur.g.exampleBuildId = r.id; cur.g.detail = excerpt(r.errorDetail) || cur.g.detail; }
    if (t < cur.earliest) { cur.earliest = t; cur.g.firstSeen = r.createdAt.toISOString(); }
  }
  return [...by.values()].map(({ g, users }) => ({ ...g, accounts: users.size })).sort((a, b) => b.count - a.count || b.lastSeen.localeCompare(a.lastSeen));
}

function excerpt(d: string | null | undefined): string {
  return d ? d.replace(/\s+\n/g, "\n").trim().slice(0, 600) : "";
}

/** The plain-text bug report for one group: what, how often, an example build. No prompt, no email, no secrets. */
export function errorReport(g: ErrorGroup, origin = ""): string {
  const link = `${origin.replace(/\/+$/, "")}/admin/cyrus/builds/${g.exampleBuildId}`;
  return [
    `Cyrus build error: ${g.errorCode ?? "no code"}`,
    `Message: ${g.line}`,
    `Seen: ${g.count} build(s), ${g.accounts} account(s)`,
    `First / last seen: ${g.firstSeen} / ${g.lastSeen}`,
    ...(g.models.length ? [`Models: ${g.models.join(", ")}`] : []),
    `Example build: ${link}`,
    ...(g.detail ? ["", "Detail:", g.detail] : []),
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Detail of one build (the drawer)
// ---------------------------------------------------------------------------

export type LiveEvent = { at: string; stage: string; message: string };
export type LiveDetail = {
  id: string;
  /** the full prompt (and the change request when this is an iteration) */
  prompt: string;
  changeRequest: string | null;
  account: string;
  email: string | null;
  events: LiveEvent[];
  live: { costUsd: number; turns?: number; phase?: string; stage?: string } | null;
  error: string | null;
  errorDetail: string | null;
  /** true when the events came from the build service just now (an in-progress build) rather than the stored copy */
  fresh: boolean;
};

/** Tolerant read of events / live from a stored ModBuild.result or a service record. */
export function readProgress(v: unknown): { events: LiveEvent[]; live: LiveDetail["live"] } {
  const o = v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {};
  const ev = Array.isArray(o.events) ? o.events : [];
  const events = ev
    .filter((e): e is Record<string, unknown> => !!e && typeof e === "object")
    .slice(-60)
    .map((e) => ({ at: String(e.at ?? "").slice(0, 40), stage: String(e.stage ?? "").slice(0, 30), message: String(e.message ?? "").slice(0, 240) }));
  const l = o.live && typeof o.live === "object" ? (o.live as Record<string, unknown>) : null;
  const live = l && typeof l.costUsd === "number" && Number.isFinite(l.costUsd)
    ? { costUsd: l.costUsd, ...(typeof l.turns === "number" ? { turns: l.turns } : {}), ...(typeof l.phase === "string" ? { phase: l.phase.slice(0, 40) } : {}), ...(typeof l.stage === "string" ? { stage: l.stage.slice(0, 40) } : {}) }
    : null;
  return { events, live };
}
EOF

