// Cyrus admin "Live" tab: the DB reads behind the feed API and the page's first paint. SERVER ONLY, read-only.
// Cyrus tables via cyrusDb only (host seam). Running builds are topped up from the build service (svcGet, short timeout)
// so the cost and events are fresh even when no customer is polling the build.
import { cyrusDb } from "../db";
import { svcGet } from "../../modbuilder/client";
import { emailMap, gameOfBuild, modelOfBuild } from "./data";
import { buildOutcome } from "./metrics";
import { LIVE_MAX_ROWS, LIVE_WINDOW_MS, groupErrors, readProgress, toLiveRow, type ErrorGroup, type LiveDetail, type LiveRow } from "./live";

const ERROR_WINDOW_MS = 7 * 86_400_000;

export type LiveFeed = { at: string; rows: LiveRow[]; groups: ErrorGroup[]; counts: { running: number; failed: number; succeeded: number; total: number } };

const withTimeout = <T,>(p: Promise<T>, ms: number): Promise<T | null> =>
  Promise.race([p, new Promise<null>((r) => setTimeout(() => r(null), ms))]).catch(() => null);

export async function loadLiveFeed(now = new Date()): Promise<LiveFeed> {
  const since = new Date(now.getTime() - LIVE_WINDOW_MS);
  const [rows, failed] = await Promise.all([
    cyrusDb.modBuild.findMany({
      where: { createdAt: { gt: since } },
      select: { id: true, userId: true, status: true, errorCode: true, error: true, costUsd: true, durationMs: true, createdAt: true, cyrus: true, prompt: true, changeRequest: true, mcVersion: true },
      orderBy: { createdAt: "desc" },
      take: LIVE_MAX_ROWS,
    }),
    cyrusDb.modBuild.findMany({
      where: { status: "failed", createdAt: { gt: new Date(now.getTime() - ERROR_WINDOW_MS) } },
      select: { id: true, userId: true, status: true, errorCode: true, error: true, createdAt: true, cyrus: true, mcVersion: true },
      orderBy: { createdAt: "desc" },
      take: 1500,
    }),
  ]);
  const runningIds = rows.filter((r) => buildOutcome(r) === "running").map((r) => r.id).slice(0, 25);
  const [stored, fresh, emails] = await Promise.all([
    runningIds.length ? cyrusDb.modBuild.findMany({ where: { id: { in: runningIds } }, select: { id: true, result: true } }) : [],
    Promise.all(runningIds.slice(0, 10).map(async (id) => [id, await withTimeout(svcGet(id).then((s) => s as unknown), 2000)] as const)),
    emailMap(rows.map((r) => r.userId)),
  ]);
  const liveCost = new Map<string, number>();
  for (const s of stored) { const p = readProgress(s.result); if (p.live) liveCost.set(s.id, p.live.costUsd); }
  for (const [id, svc] of fresh) { const p = readProgress(svc); if (p.live) liveCost.set(id, Math.max(liveCost.get(id) ?? 0, p.live.costUsd)); }
  const out = rows.map((r) => toLiveRow({ ...r, costUsd: r.costUsd || 0, model: modelOfBuild(r), game: gameOfBuild(r), liveCostUsd: liveCost.get(r.id) ?? null }, emails.get(r.userId)));
  const groups = groupErrors(failed.map((r) => ({ ...r, model: modelOfBuild(r) })));
  const counts = { running: 0, failed: 0, succeeded: 0, total: out.length };
  for (const r of out) { if (r.outcome === "running") counts.running++; else if (r.outcome === "failed" || r.outcome === "refused") counts.failed++; else if (r.outcome === "succeeded") counts.succeeded++; }
  return { at: now.toISOString(), rows: out, groups, counts };
}

/** One build for the drawer: full prompt, events and live cost (fresh from the service while it runs). null = no such build. */
export async function loadLiveDetail(id: string): Promise<LiveDetail | null> {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return null;
  const row = await cyrusDb.modBuild.findUnique({ where: { id }, select: { id: true, userId: true, status: true, errorCode: true, error: true, prompt: true, changeRequest: true, result: true } });
  if (!row) return null;
  let progress = readProgress(row.result);
  let fresh = false;
  if (buildOutcome(row) === "running") {
    const svc = await withTimeout(svcGet(id).then((s) => s as unknown), 2500);
    const p = svc ? readProgress(svc) : null;
    if (p && (p.events.length || p.live)) { progress = { events: p.events.length ? p.events : progress.events, live: p.live ?? progress.live }; fresh = true; }
  }
  const emails = await emailMap([row.userId]);
  const res = row.result && typeof row.result === "object" ? (row.result as { errorDetail?: unknown }) : {};
  const email = emails.get(row.userId) ?? null;
  return {
    id: row.id,
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    account: row.userId,
    email,
    events: progress.events,
    live: progress.live,
    error: row.error,
    errorDetail: typeof res.errorDetail === "string" ? res.errorDetail.slice(0, 2000) : null,
    fresh,
  };
}
EOF
