// Cyrus admin Live tab (2026-10-13): GET -> the feed (last 24 h, newest first) + error groups; GET ?id=<buildId> -> one
// build's full prompt and progress. Same guard as the pages (real account, not impersonating, preview list, fleet area);
// anything else is a plain 404. Opening a build's detail is audited (it shows the whole prompt); the 5 s feed poll is not.
import { cyrusAdminApiUser } from "@/lib/cyrus/admin/gate";
import { cyrusAudit } from "@/lib/cyrus/admin/audit";
import { loadLiveDetail, loadLiveFeed } from "@/lib/cyrus/admin/live-data";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const NO_STORE = { "cache-control": "no-store" };

export async function GET(req: Request) {
  const admin = await cyrusAdminApiUser("live.view");
  if (!admin) return new Response("Not found", { status: 404 });
  const id = new URL(req.url).searchParams.get("id");
  try {
    if (id) {
      const d = await loadLiveDetail(id);
      if (!d) return Response.json({ error: "not_found" }, { status: 404, headers: NO_STORE });
      await cyrusAudit({ actorId: admin.id, action: "live.view", target: `build:${d.id}`, note: "prompt and progress opened in the Live drawer" });
      return Response.json(d, { headers: NO_STORE });
    }
    return Response.json(await loadLiveFeed(), { headers: NO_STORE });
  } catch (e) {
    console.error("[cyrus-admin] live feed failed", (e as Error).message);
    return Response.json({ error: "unavailable" }, { status: 503, headers: NO_STORE });
  }
}
