"use client";
// Cyrus admin Live tab: polls /api/admin/cyrus/live every 5 s (no websockets), filters client-side, opens a detail drawer
// for one build and copies a grouped error as a plain-text report. Uses only the admin portal's shared classes so dark and
// light both come from app/admin/admin-shell.css. The feed carries MASKED account labels; the drawer adds the full email
// (the detail call is audited on the server).
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { LIVE_FILTERS, LIVE_POLL_MS, errorReport, filterLive, type ErrorGroup, type LiveDetail, type LiveFilter, type LiveRow } from "@/lib/cyrus/admin/live";
import { Badge } from "@/components/ui/primitives";

type Feed = { at: string; rows: LiveRow[]; groups: ErrorGroup[]; counts: { running: number; failed: number; succeeded: number; total: number } };

const usd = (x: number) => `$${x.toFixed(x < 1 ? 3 : 2)}`;
const secs = (ms: number | null) => (!ms ? "–" : ms < 60_000 ? `${Math.round(ms / 1000)}s` : `${(ms / 60_000).toFixed(1)}m`);
const clock = (iso: string) => iso.slice(11, 19);
const tone = (o: string) => (o === "succeeded" ? "green" : o === "running" ? "brand" : o === "refused" ? "amber" : o === "failed" ? "red" : "slate");

export function LiveFeed({ initial, origin }: { initial: Feed; origin: string }) {
  const [feed, setFeed] = useState<Feed>(initial);
  const [filter, setFilter] = useState<LiveFilter>("all");
  const [paused, setPaused] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const [detail, setDetail] = useState<LiveDetail | null>(null);
  const [detailErr, setDetailErr] = useState<string | null>(null);
  const [copied, setCopied] = useState<string | null>(null);
  const alive = useRef(true);

  const poll = useCallback(async () => {
    try {
      const r = await fetch("/api/admin/cyrus/live", { cache: "no-store" });
      if (!r.ok) throw new Error(String(r.status));
      const j = (await r.json()) as Feed;
      if (alive.current) { setFeed(j); setErr(null); }
    } catch { if (alive.current) setErr("Could not refresh. Retrying every 5 s."); }
  }, []);

  useEffect(() => {
    alive.current = true;
    if (paused) return () => { alive.current = false; };
    const t = setInterval(() => { if (document.visibilityState === "visible") void poll(); }, LIVE_POLL_MS);
    return () => { alive.current = false; clearInterval(t); };
  }, [paused, poll]);

  // the drawer re-reads its build every 5 s while that build is still running
  const openId = open;
  const running = feed.rows.find((r) => r.id === openId)?.outcome === "running";
  useEffect(() => {
    if (!openId) return;
    let stop = false;
    const load = async () => {
      try {
        const r = await fetch(`/api/admin/cyrus/live?id=${encodeURIComponent(openId)}`, { cache: "no-store" });
        if (!r.ok) throw new Error();
        const j = (await r.json()) as LiveDetail;
        if (!stop) { setDetail(j); setDetailErr(null); }
      } catch { if (!stop) setDetailErr("Could not load this build."); }
    };
    setDetail(null); setDetailErr(null);
    void load();
    const t = running ? setInterval(load, LIVE_POLL_MS) : null;
    return () => { stop = true; if (t) clearInterval(t); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openId, running]);

  const now = new Date(feed.at);
  const rows = useMemo(() => filterLive(feed.rows, filter, now), [feed, filter]); // eslint-disable-line react-hooks/exhaustive-deps
  const copy = async (key: string, text: string) => {
    try { await navigator.clipboard.writeText(text); setCopied(key); setTimeout(() => setCopied((c) => (c === key ? null : c)), 2000); } catch { setCopied(null); }
  };

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center gap-2" role="group" aria-label="Filter">
        {LIVE_FILTERS.map((f) => (
          <button key={f.id} type="button" aria-pressed={filter === f.id} onClick={() => setFilter(f.id)} className={filter === f.id ? "btn-primary text-xs" : "btn-secondary text-xs"}>
            {f.label}{f.id === "running" ? ` (${feed.counts.running})` : f.id === "failed" ? ` (${feed.counts.failed})` : f.id === "succeeded" ? ` (${feed.counts.succeeded})` : ""}
          </button>
        ))}
        <span className="ml-auto flex items-center gap-2 text-xs text-slate-500" aria-live="polite">
          {err ? <span className="text-red-400">{err}</span> : paused ? "Paused" : `Updated ${clock(feed.at)} UTC, every ${LIVE_POLL_MS / 1000} s`}
          <button type="button" className="btn-ghost text-xs" onClick={() => { setPaused((p) => !p); if (paused) void poll(); }}>{paused ? "Resume" : "Pause"}</button>
        </span>
      </div>

      {rows.length === 0 ? (
        <div className="rounded-lg border border-dashed border-white/10 px-4 py-6 text-center text-sm text-slate-400" data-empty>Nothing matches this filter in the last 24 hours.</div>
      ) : (
        <div className="-mx-1 overflow-x-auto px-1">
          <table className="w-full text-sm" data-testid="live-feed">
            <thead><tr className="text-left text-xs font-medium text-slate-500 [&>th]:px-2 [&>th]:py-1.5 [&>th]:whitespace-nowrap"><th>Time</th><th>Account</th><th>Prompt</th><th>Model</th><th>Status</th><th className="text-right">Cost</th><th className="text-right">Time taken</th><th>Error</th></tr></thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id} className="cursor-pointer border-t border-white/[0.06] align-top hover:bg-white/[0.03] [&>td]:px-2 [&>td]:py-1.5" onClick={() => setOpen(r.id)} tabIndex={0} onKeyDown={(e) => { if (e.key === "Enter") setOpen(r.id); }} aria-label={`Open build ${r.id}`}>
                  <td className="whitespace-nowrap tabular-nums text-xs text-slate-400" title={r.at}>{clock(r.at)}</td>
                  <td className="whitespace-nowrap text-xs">{r.account}</td>
                  <td className="max-w-[320px]"><div className="truncate" title={r.prompt}>{r.prompt}</div><div className="text-xs text-slate-500">{r.game} {r.mcVersion}</div></td>
                  <td className="capitalize">{r.model}</td>
                  <td><Badge tone={tone(r.outcome)}>{r.outcome}</Badge>{r.outcome === "running" ? <div className="text-xs text-slate-500">{r.status}</div> : null}</td>
                  <td className="whitespace-nowrap text-right tabular-nums">{usd(r.costUsd)}{r.costLive ? <span className="text-xs text-slate-500" title="running estimate"> so far</span> : null}</td>
                  <td className="text-right tabular-nums">{secs(r.durationMs)}</td>
                  <td className="max-w-[220px] truncate text-xs text-slate-400" title={r.error ?? ""}>{r.errorCode ?? "–"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <section className="card mt-6 min-w-0" aria-labelledby="live-errors">
        <h2 id="live-errors" className="text-sm font-semibold">Bugs and errors</h2>
        <p className="mt-0.5 text-xs text-slate-400">Failed builds of the last 7 days grouped by error code and first error line (safety refusals and cancels are not bugs and are left out).</p>
        {feed.groups.length === 0 ? (
          <div className="mt-3 rounded-lg border border-dashed border-white/10 px-4 py-6 text-center text-sm text-slate-400" data-empty>No failed builds in the last 7 days.</div>
        ) : (
          <ul className="mt-3 divide-y divide-white/[0.06]">
            {feed.groups.slice(0, 30).map((g) => (
              <li key={g.key} className="flex flex-col gap-2 py-3 sm:flex-row sm:items-start sm:justify-between">
                <div className="min-w-0 text-sm">
                  <p className="flex flex-wrap items-center gap-2"><Badge tone="red">{g.count}x</Badge>{g.errorCode ? <code className="text-xs">{g.errorCode}</code> : null}<span className="text-xs text-slate-500">{g.accounts} account(s) · last {g.lastSeen.slice(0, 16).replace("T", " ")} UTC</span></p>
                  <p className="mt-1 break-words">{g.line}</p>
                </div>
                <div className="flex flex-none gap-2">
                  <button type="button" className="btn-secondary text-xs" onClick={() => setOpen(g.exampleBuildId)}>Example build</button>
                  <button type="button" className="btn-secondary text-xs" onClick={() => copy(g.key, errorReport(g, origin))}>{copied === g.key ? "Copied" : "Copy as report"}</button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      {open ? (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/50" role="dialog" aria-modal="true" aria-label="Build detail" onClick={() => setOpen(null)}>
          <aside className="h-full w-full max-w-xl overflow-y-auto border-l border-white/10 bg-[var(--adm-surface,#0b1020)] p-4 text-sm shadow-xl" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-center justify-between gap-2">
              <h2 className="min-w-0 truncate font-mono text-xs">{open}</h2>
              <div className="flex gap-2">
                <a className="btn-secondary text-xs" href={`/admin/cyrus/builds/${encodeURIComponent(open)}`}>Full page</a>
                <button type="button" className="btn-primary text-xs" onClick={() => setOpen(null)} autoFocus>Close</button>
              </div>
            </div>
            {detailErr ? <p className="text-red-400">{detailErr}</p> : !detail ? <p className="text-slate-400">Loading…</p> : (
              <div className="grid gap-4">
                <div>
                  <h3 className="text-xs font-medium text-slate-500">Account</h3>
                  <p>{detail.email ?? detail.account}</p>
                </div>
                <div>
                  <h3 className="text-xs font-medium text-slate-500">Prompt</h3>
                  <p className="whitespace-pre-wrap break-words">{detail.prompt}</p>
                  {detail.changeRequest ? <><h3 className="mt-2 text-xs font-medium text-slate-500">Change request</h3><p className="whitespace-pre-wrap break-words">{detail.changeRequest}</p></> : null}
                </div>
                {detail.live ? (
                  <div>
                    <h3 className="text-xs font-medium text-slate-500">Live</h3>
                    <p>{usd(detail.live.costUsd)} so far{detail.live.turns != null ? ` · ${detail.live.turns} turn(s)` : ""}{detail.live.phase ? ` · ${detail.live.phase}` : ""}{detail.live.stage ? ` · ${detail.live.stage}` : ""}{detail.fresh ? " · from the build service just now" : " · stored copy"}</p>
                  </div>
                ) : null}
                {detail.error ? (
                  <div>
                    <h3 className="text-xs font-medium text-slate-500">Error</h3>
                    <p className="break-words text-red-300">{detail.error}</p>
                    {detail.errorDetail ? <pre className="mt-1 max-h-48 overflow-auto rounded bg-black/30 p-2 text-xs">{detail.errorDetail}</pre> : null}
                  </div>
                ) : null}
                <div>
                  <h3 className="text-xs font-medium text-slate-500">Progress ({detail.events.length})</h3>
                  {detail.events.length === 0 ? <p className="text-slate-400">No events yet.</p> : (
                    <ol className="mt-1 grid gap-1 text-xs">
                      {detail.events.map((e, i) => <li key={i} className="flex gap-2"><span className="flex-none tabular-nums text-slate-500">{e.at.slice(11, 19)}</span><span className="flex-none rounded bg-white/5 px-1">{e.stage}</span><span className="min-w-0 break-words">{e.message}</span></li>)}
                    </ol>
                  )}
                </div>
              </div>
            )}
          </aside>
        </div>
      ) : null}
    </div>
  );
}
