import type { Metadata } from "next";
import { headers } from "next/headers";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { cyrusAudit } from "@/lib/cyrus/admin/audit";
import { loadLiveFeed } from "@/lib/cyrus/admin/live-data";
import { LiveFeed } from "@/components/admin/cyrus/LiveFeed";
import { Section } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Live");
}

/**
 * Live (2026-10-13): what people are doing right now. Every prompt/build of the last 24 h, refreshed every 5 s by polling
 * /api/admin/cyrus/live (no websockets), a detail drawer with the build's events and live cost, and the failed builds
 * grouped into bugs. Read-only; opening a build's prompt is audited (action live.view).
 */
export default async function CyrusAdminLive() {
  const admin = await requireCyrusAdmin("live");
  const feed = await loadLiveFeed();
  const h = await headers();
  const host = h.get("x-forwarded-host") ?? h.get("host") ?? "";
  const origin = host ? `${h.get("x-forwarded-proto") ?? "https"}://${host.split(",")[0].trim()}` : "";
  await cyrusAudit({ actorId: admin.id, action: "live.view", target: "feed", note: "Live tab opened" });
  return (
    <Section title="Live" sub="Newest first, last 24 hours. Accounts are masked here; opening a row shows the full prompt and is written to the audit log. A running build's cost is the build service's running estimate, not a charge.">
      <LiveFeed initial={feed} origin={origin} />
    </Section>
  );
}
