                  <td className="whitespace-nowrap tabular-nums text-xs text-slate-400" title={r.at}>{clock(r.at)}</td>
                  <td className="whitespace-nowrap text-xs">{r.account}</td>
                  <td className="max-w-[320px]"><div className="truncate" title={r.prompt}>{r.prompt}</div><div className="text-xs text-slate-500">{r.game} {r.mcVersion}</div></td>
