          <aside className="h-full w-full max-w-xl overflow-y-auto border-l border-white/10 bg-[var(--adm-surface,#0b1020)] p-4 text-sm shadow-xl" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-center justify-between gap-2">
              <h2 className="min-w-0 truncate font-mono text-xs">{open}</h2>
              <div className="flex gap-2">
                <a className="btn-secondary text-xs" href={`/admin/cyrus/builds/${encodeURIComponent(open)}`}>Full page</a>
                <button type="button" className="btn-primary text-xs" onClick={() => setOpen(null)} autoFocus>Close</button>
              </div>
            </div>
            {detailErr ? <p className="text-red-400">{detailErr}</p> : !detail ? <p className="text-slate-400">Loading…</p> : (
              <div className="grid gap-4">
                <div>
                  <h3 className="text-xs font-medium text-slate-500">Account</h3>
                  <p>{detail.email ?? detail.account}</p>
                </div>
                <div>
                  <h3 className="text-xs font-medium text-slate-500">Prompt</h3>
                  <p className="whitespace-pre-wrap break-words">{detail.prompt}</p>
                  {detail.changeRequest ? <><h3 className="mt-2 text-xs font-medium text-slate-500">Change request</h3><p className="whitespace-pre-wrap break-words">{detail.changeRequest}</p></> : null}
                </div>
                {detail.live ? (
                  <div>
                    <h3 className="text-xs font-medium text-slate-500">Live</h3>
                    <p>{usd(detail.live.costUsd)} so far{detail.live.turns != null ? ` · ${detail.live.turns} turn(s)` : ""}{detail.live.phase ? ` · ${detail.live.phase}` : ""}{detail.live.stage ? ` · ${detail.live.stage}` : ""}{detail.fresh ? " · from the build service just now" : " · stored copy"}</p>
                  </div>
                ) : null}
                {detail.error ? (
                  <div>
                    <h3 className="text-xs font-medium text-slate-500">Error</h3>
                    <p className="break-words text-red-300">{detail.error}</p>
                    {detail.errorDetail ? <pre className="mt-1 max-h-48 overflow-auto rounded bg-black/30 p-2 text-xs">{detail.errorDetail}</pre> : null}
