import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { cutPrompt, errorReport, filterLive, firstLine, groupErrors, maskEmail, normaliseError, readProgress, toLiveRow } from "../lib/cyrus/admin/live";
import { CYRUS_ADMIN_TABS, canCyrusAdmin, canSeeCyrusTab } from "../lib/cyrus/admin/perms";

const now = new Date("2026-10-13T12:00:00Z");
const src = (o: Record<string, unknown> = {}) => ({ id: "b1", userId: "u1", status: "succeeded", errorCode: null, error: null, costUsd: 0.12, durationMs: 90_000, createdAt: new Date(now.getTime() - 600_000), prompt: "make a thing", mcVersion: "1.21.11", model: "saka", game: "minecraft", ...o });

describe("cyrus admin live: rows", () => {
  it("masks the account and keeps only the domain", () => {
    assert.equal(maskEmail("jane.doe@gmail.com"), "j***@gmail.com");
    assert.equal(maskEmail(null, "abcdef123"), "user abcdef");
    assert.equal(maskEmail("nonsense"), "unknown");
  });
  it("cuts a long prompt and says so", () => {
    const c = cutPrompt("x ".repeat(200));
    assert.equal(c.cut, true);
    assert.ok(c.text.length <= 140);
    assert.equal(cutPrompt("short  prompt").text, "short prompt");
  });
  it("a running build shows the live cost estimate, a settled one its own cost", () => {
    const run = toLiveRow(src({ status: "coding", costUsd: 0, liveCostUsd: 0.31 }), "a@b.co");
    assert.equal(run.outcome, "running");
    assert.equal(run.costUsd, 0.31);
    assert.equal(run.costLive, true);
    const done = toLiveRow(src({ liveCostUsd: 9 }), "a@b.co");
    assert.equal(done.costUsd, 0.12);
    assert.equal(done.costLive, false);
    assert.equal(done.account, "a***@b.co");
  });
  it("filters: running, failed (includes refused), succeeded, last hour", () => {
    const rows = [
      toLiveRow(src({ id: "r", status: "coding" }), null),
      toLiveRow(src({ id: "f", status: "failed", errorCode: "compile_failed", error: "x" }), null),
      toLiveRow(src({ id: "x", status: "failed", errorCode: "refused" }), null),
      toLiveRow(src({ id: "s" }), null),
      toLiveRow(src({ id: "old", createdAt: new Date(now.getTime() - 7_200_000) }), null),
    ];
    assert.deepEqual(filterLive(rows, "running", now).map((r) => r.id), ["r"]);
    assert.deepEqual(filterLive(rows, "failed", now).map((r) => r.id), ["f", "x"]);
    assert.deepEqual(filterLive(rows, "succeeded", now).map((r) => r.id), ["s", "old"]);
    assert.deepEqual(filterLive(rows, "1h", now).map((r) => r.id), ["r", "f", "x", "s"]);
    assert.equal(filterLive(rows, "all", now).length, 5);
  });
});

describe("cyrus admin live: bugs and errors", () => {
  const f = (id: string, user: string, line: string, mins: number, code: string | null = "compile_failed") => ({ id, userId: user, status: "failed", errorCode: code, error: line, createdAt: new Date(now.getTime() - mins * 60_000), model: "saka" });
  it("normalises per-build noise so equal bugs group", () => {
    assert.equal(normaliseError("Compile failed at line 12 for 'Foo' cabc1234567890abcdefghijkl"), normaliseError("Compile failed at line 99 for 'Bar' cxyz1234567890abcdefghijkl"));
    assert.equal(firstLine("\n  first\nsecond"), "first");
  });
  it("groups by code + first line, counts accounts, picks the latest example, drops refusals and cancels", () => {
    const g = groupErrors([
      f("a", "u1", "Compile failed at line 12", 50),
      f("b", "u2", "Compile failed at line 40\nmore", 10),
      f("c", "u2", "Builder unreachable", 5, "unreachable"),
      f("d", "u3", "blocked", 1, "refused"),
      f("e", "u3", "stopped", 1, "cancelled"),
    ]);
    assert.equal(g.length, 2);
    assert.equal(g[0].count, 2);
    assert.equal(g[0].accounts, 2);
    assert.equal(g[0].exampleBuildId, "b");
    assert.equal(g[0].errorCode, "compile_failed");
    assert.equal(g[1].errorCode, "unreachable");
  });
  it("the copy-as-report text has the code, count, link and no prompt or email", () => {
    const [g] = groupErrors([f("b", "u2", "Compile failed at line 40", 10)]);
    const t = errorReport(g, "https://x.test/");
    assert.match(t, /compile_failed/);
    assert.match(t, /https:\/\/x\.test\/admin\/cyrus\/builds\/b/);
    assert.match(t, /1 build\(s\), 1 account\(s\)/);
    assert.doesNotMatch(t, /@/);
  });
});

describe("cyrus admin live: progress + perms", () => {
  it("reads events and the live cost tolerantly", () => {
    const p = readProgress({ events: [{ at: "2026-10-13T12:00:01Z", stage: "coding", message: "Writing Main.java" }, null, 4], live: { costUsd: 0.2, turns: 3, phase: "gen" } });
    assert.equal(p.events.length, 1);
    assert.deepEqual(p.live, { costUsd: 0.2, turns: 3, phase: "gen" });
    assert.deepEqual(readProgress("junk"), { events: [], live: null });
    assert.equal(readProgress({ live: { costUsd: "x" } }).live, null);
  });
  it("Live is an ADMIN (fleet) tab and its detail view is audited as an action", () => {
    assert.ok(CYRUS_ADMIN_TABS.some((t) => t.id === "live" && t.area === "fleet"));
    assert.ok(canSeeCyrusTab("ADMIN", "live"));
    assert.ok(!canSeeCyrusTab("SUPPORT", "live"));
    assert.ok(!canSeeCyrusTab("BILLING", "live"));
    assert.ok(canCyrusAdmin("ADMIN", "live.view"));
    assert.ok(!canCyrusAdmin("BILLING", "live.view"));
  });
});
