export async function getAnthropicCosts(opts: { env?: Record<string, string | undefined>; fetchImpl?: FetchLike; now?: Date } = {}): Promise<AnthropicCostState> {
  const key = (opts.env ?? process.env).ANTHROPIC_ADMIN_API_KEY?.trim();
