"use client";
// Cyrus admin Economy: editable pricing / margin controls with a LIVE preview of what the unsaved values do to every
// plan's margin. Each row saves ONE setting through the existing audited action (adminCyrusSetSetting); the preview is the
// same pure code the server page uses (lib/cyrus/admin/economy.ts). Warnings are soft: nothing here blocks a save (D-62).
import { useMemo, useState } from "react";
import { adminCyrusSetSetting } from "@/lib/actions-cyrus-admin";
import { previewEconomics, type ModelCost } from "@/lib/cyrus/admin/economy";
import type { CyrusModelId } from "@/lib/cyrus/models";

export type EditRow = { key: string; label: string; hint: string; current: string; def: string; unit?: string };

const usd = (x: number) => `${x < 0 ? "-" : ""}$${Math.abs(x).toFixed(2)}`;

export function EconomyControls({ stored, rows, costs, canSet, back }: { stored: Record<string, string>; rows: EditRow[]; costs: Record<CyrusModelId, ModelCost>; canSet: boolean; back: string }) {
  const [draft, setDraft] = useState<Record<string, string>>({});
  const changed = Object.entries(draft).filter(([k, v]) => v.trim() !== (rows.find((r) => r.key === k)?.current ?? ""));
  const applied = useMemo(() => Object.fromEntries(changed.filter(([, v]) => v.trim() !== "" && Number.isFinite(Number(v))).map(([k, v]) => [k, v.trim()])), [draft]); // eslint-disable-line react-hooks/exhaustive-deps
  const before = useMemo(() => previewEconomics(stored, {}, costs), [stored, costs]);
  const after = useMemo(() => previewEconomics(stored, applied, costs), [stored, applied, costs]);
  const dirty = Object.keys(applied).length > 0;
  const warnings = after.plans.flatMap((p) => p.warnings);

  return (
    <div className="grid gap-5 lg:grid-cols-2">
      <div className="min-w-0">
        <ul className="grid gap-2">
          {rows.map((r) => {
            const v = draft[r.key] ?? r.current;
            const isDirty = r.key in applied;
            return (
              <li key={r.key}>
                <form action={adminCyrusSetSetting} className="grid grid-cols-[minmax(0,1fr)_7rem_auto] items-center gap-2">
                  <input type="hidden" name="key" value={r.key} />
                  <input type="hidden" name="back" value={back} />
                  <label className="min-w-0 text-sm" htmlFor={`ec-${r.key}`}>
                    <span className="block truncate">{r.label}</span>
                    <span className="block truncate text-xs text-slate-500" title={r.hint}>{r.hint} Default {r.def}{r.unit ? ` ${r.unit}` : ""}.</span>
                  </label>
                  <input id={`ec-${r.key}`} name="value" inputMode="decimal" className="input w-full text-right text-sm tabular-nums" value={v} onChange={(e) => setDraft((d) => ({ ...d, [r.key]: e.target.value }))} disabled={!canSet} aria-describedby="ec-preview" />
                  <button className={isDirty ? "btn-primary text-xs" : "btn-secondary text-xs"} disabled={!canSet || !isDirty}>Save</button>
                </form>
              </li>
            );
          })}
        </ul>
        {!canSet ? <p className="mt-3 text-xs text-slate-500">Your role can read this tab but not change settings.</p> : null}
        {dirty ? <button type="button" className="btn-ghost mt-3 text-xs" onClick={() => setDraft({})}>Discard unsaved changes</button> : null}
      </div>

      <div className="min-w-0" id="ec-preview" aria-live="polite">
        <h3 className="mb-2 text-xs font-medium text-slate-500">{dirty ? "What the unsaved values do (per subscriber, per month, worst case: every token spent)" : "Today (change a value to preview)"}</h3>
        <div className="-mx-1 overflow-x-auto px-1">
          <table className="w-full text-sm">
            <thead><tr className="text-left text-xs font-medium text-slate-500 [&>th]:px-2 [&>th]:py-1.5"><th>Plan</th><th className="text-right">Price</th><th className="text-right">AI cost</th><th className="text-right">After fees</th><th className="text-right">Margin</th></tr></thead>
            <tbody>
              {after.plans.map((p, i) => {
                const b = before.plans[i];
                const d = p.marginAfterFeesPct - b.marginAfterFeesPct;
                const bad = p.marginAfterFeesUsd < 0;
                const thin = !bad && p.marginAfterFeesPct < after.fees.marginWarnPct;
                return (
                  <tr key={p.tier} className="border-t border-white/[0.06] [&>td]:px-2 [&>td]:py-1.5">
                    <td>{p.label}</td>
                    <td className="text-right tabular-nums">{usd(p.priceUsd)}</td>
                    <td className="text-right tabular-nums">{usd(p.worstCostUsd)}</td>
                    <td className="text-right tabular-nums">{usd(p.marginAfterFeesUsd)}</td>
                    <td className={`text-right tabular-nums ${bad ? "text-red-400" : thin ? "text-amber-400" : "text-emerald-400"}`}>{p.marginAfterFeesPct.toFixed(0)}%{dirty && Math.abs(d) >= 0.5 ? <span className="text-xs text-slate-500"> ({d > 0 ? "+" : ""}{d.toFixed(0)})</span> : null}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <p className="mt-2 text-xs text-slate-400">Starter grant: {after.starter.tokens} tokens, up to {usd(after.starter.worstUsd)} of AI per new account. A {usd(after.topup.paidUsd)} top-up: {after.topup.tokens} tokens, margin after fees {after.topup.marginAfterFeesPct.toFixed(0)}%.</p>
        {warnings.length ? (
          <ul className="mt-3 grid gap-1.5" role="status">
            {warnings.map((w, i) => <li key={i} className={`rounded-lg border px-3 py-2 text-xs ${w.level === "red" ? "border-red-500/30 bg-red-500/10 text-red-300" : "border-amber-500/30 bg-amber-500/10 text-amber-300"}`}>{w.text} You can still save: this is a warning, not a block.</li>)}
          </ul>
        ) : null}
      </div>
    </div>
  );
}
EOF

