import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/lib/db";
import { cyrusDb } from "@/lib/cyrus/db";
import { realUser } from "@/lib/auth";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { canCyrusAdmin } from "@/lib/cyrus/admin/perms";
import { emailMap, modelOfBuild } from "@/lib/cyrus/admin/data";
import { callsOfResult, COST_SETTINGS, parseCostCaps, spendByModel, spendByUser, utcDayStart } from "@/lib/cyrus/admin/cost";
import { ECON_DEFAULTS, ECON_EDIT_KEYS, ECON_SETTINGS, medianCostByModel, previewEconomics, spendByDay } from "@/lib/cyrus/admin/economy";
import { getAnthropicCosts } from "@/lib/cyrus/admin/anthropic-cost";
import { cyrusSettingDef } from "@/lib/cyrus/admin/settings-catalog";
import { CYRUS_TOKEN_DEFAULTS } from "@/lib/cyrus/tokens/config";
import { CYRUS_MODELS } from "@/lib/cyrus/models";
import { EconomyControls, type EditRow } from "@/components/admin/cyrus/EconomyControls";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Flash, Section, TableWrap, UserLink, n, tdRow, thCls, usd } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Economy");
}

const DAY = 86_400_000;
const HINT: Record<string, string> = {
  cyrus_tok_tokens_per_usd: "Tokens charged per 1 USD of AI cost.",
  cyrus_tok_mult_katara: "Multiplier on Katara builds.",
  cyrus_tok_mult_saka: "Multiplier on Saka builds.",
  cyrus_tok_mult_yakko: "Premium multiplier on Yakko builds.",
  cyrus_tok_plan_katara_cents: "Katara monthly price in cents (the Stripe Price is the real charge).",
  cyrus_tok_plan_saka_cents: "Saka monthly price in cents.",
  cyrus_tok_plan_all_cents: "All models monthly price in cents.",
  cyrus_tok_plan_katara_tokens: "Tokens Katara includes each month.",
  cyrus_tok_plan_saka_tokens: "Tokens Saka includes each month.",
  cyrus_tok_plan_all_tokens: "Tokens All models includes each month.",
  cyrus_tok_starter: "One-time free tokens for a new account (0 = off).",
  cyrus_tok_topup_tokens_per_usd: "Tokens per 1 USD on a one-off top-up.",
  cyrus_econ_stripe_pct: "Card fee percentage.",
  cyrus_econ_stripe_fixed_cents: "Card fee fixed part, cents.",
  cyrus_econ_margin_warn_pct: "Warn below this margin after fees.",
};
const LABEL = (k: string) => cyrusSettingDef(k)?.label ?? k;
const DEFAULT_OF = (k: string) => (k in CYRUS_TOKEN_DEFAULTS ? CYRUS_TOKEN_DEFAULTS[k as keyof typeof CYRUS_TOKEN_DEFAULTS] : String(ECON_DEFAULTS[(Object.keys(ECON_SETTINGS) as (keyof typeof ECON_SETTINGS)[]).find((x) => ECON_SETTINGS[x] === k)!]));

/**
 * Economy (2026-10-13): the projected token economy per plan from the LIVE token config, measured AI cost per build,
 * editable pricing and margin controls with a preview before saving (audited, soft warnings), measured spend per
 * day / model / account, and the optional live Anthropic cost pull (needs ANTHROPIC_ADMIN_API_KEY on the server).
 */
export default async function CyrusAdminEconomy({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
  await requireCyrusAdmin("economy");
  const me = (await realUser())!;
  const sp = await searchParams;
  const now = new Date();
  const since = new Date(now.getTime() - 30 * DAY);
  const keys = [...ECON_EDIT_KEYS, ...Object.values(COST_SETTINGS)];
  const [builds, settings, anthropic] = await Promise.all([
    cyrusDb.modBuild.findMany({ where: { createdAt: { gt: since } }, select: { id: true, userId: true, status: true, costUsd: true, createdAt: true, result: true, cyrus: true }, orderBy: { createdAt: "desc" }, take: 5000 }),
    db.setting.findMany({ where: { OR: [{ key: { startsWith: "cyrus_tok_" } }, { key: { in: keys } }] }, select: { key: true, value: true } }),
    getAnthropicCosts(),
  ]);
  const stored = Object.fromEntries(settings.map((s) => [s.key, s.value]));
  const costs = medianCostByModel(builds.map((b) => ({ model: modelOfBuild(b), costUsd: b.costUsd || 0, succeeded: b.status === "succeeded" })));
  const eco = previewEconomics(stored, {}, costs);
  const lite = builds.map((b) => ({ id: b.id, userId: b.userId, costUsd: b.costUsd || 0, createdAt: b.createdAt }));
  const days = spendByDay(lite, 30, now);
  const users = spendByUser(lite, now).slice(0, 15);
  const models = spendByModel(builds.flatMap((b) => callsOfResult(b.result)));
  const caps = parseCostCaps(stored);
  const todayUsd = lite.filter((b) => b.createdAt >= utcDayStart(now)).reduce((a, b) => a + b.costUsd, 0);
  const total30 = lite.reduce((a, b) => a + b.costUsd, 0);
  const emails = await emailMap(users.map((u) => u.userId));
  const canSet = canCyrusAdmin(me.role, "setting.set");
  const rows: EditRow[] = [...ECON_EDIT_KEYS, COST_SETTINGS.alertPlatformDailyUsd, COST_SETTINGS.alertUserDailyUsd].map((k) => ({
    key: k, label: LABEL(k), hint: HINT[k] ?? cyrusSettingDef(k)?.description.slice(0, 90) ?? "", current: stored[k] ?? DEFAULT_OF(k) ?? "", def: k in CYRUS_TOKEN_DEFAULTS || k.startsWith("cyrus_econ_") ? DEFAULT_OF(k) : "0",
  }));
  const maxDay = Math.max(0.0001, ...days.map((d) => d.usd));
  const warnings = eco.plans.flatMap((p) => p.warnings);
  const modelName = (id: string) => CYRUS_MODELS.find((m) => m.id === id)?.name ?? id;

  return (
    <div>
      <Flash sp={sp} />
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="AI spend today (UTC)" value={usd(todayUsd)} delta={caps.platformDailyCapUsd ? `cap ${usd(caps.platformDailyCapUsd)}` : "no platform cap"} deltaGood={!caps.platformDailyCapUsd || todayUsd < caps.platformDailyCapUsd} />
        <StatCard label="AI spend, 30 days" value={usd(total30)} delta={`${n(builds.length)} builds`} />
        <StatCard label="Tokens per USD" value={n(eco.cfg.tokensPerUsd)} delta={`min charge ${eco.cfg.minSpend}`} />
        <StatCard label="Plan warnings" value={n(warnings.length)} deltaGood={warnings.length === 0} delta={warnings.length ? "see below" : "margins above your line"} />
      </div>

      <Section title="Projected economy per plan" sub={`From the live token config. Worst case = every token of the month spent on the model with the cheapest multiplier. Stripe fee ${eco.fees.stripePct}% + ${eco.fees.stripeFixedCents} c; warning line ${eco.fees.marginWarnPct}% margin.`}>
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Plan</th><th className="text-right">Price</th><th className="text-right">Tokens</th><th className="text-right">AI budget</th><th className="text-right">Worst-case AI cost</th><th className="text-right">Margin before fees</th><th className="text-right">Stripe fee</th><th className="text-right">Margin after fees</th></tr></thead>
            <tbody>
              {eco.plans.map((p) => (
                <tr key={p.tier} className={tdRow}>
                  <td className="font-medium">{p.label}</td>
                  <td className="text-right tabular-nums">{usd(p.priceUsd)}</td>
                  <td className="text-right tabular-nums">{n(p.tokens)}</td>
                  <td className="text-right tabular-nums">{usd(p.budgetUsd)}</td>
                  <td className="text-right tabular-nums">{usd(p.worstCostUsd)}</td>
                  <td className="text-right tabular-nums">{usd(p.marginBeforeFeesUsd)} · {p.marginBeforeFeesPct.toFixed(0)}%</td>
                  <td className="text-right tabular-nums">{usd(p.stripeFeeUsd)}</td>
                  <td className="text-right tabular-nums">{usd(p.marginAfterFeesUsd)} · <Badge tone={p.marginAfterFeesUsd < 0 ? "red" : p.marginAfterFeesPct < eco.fees.marginWarnPct ? "amber" : "green"}>{p.marginAfterFeesPct.toFixed(0)}%</Badge></td>
                </tr>
              ))}
            </tbody>
          </table>
        </TableWrap>
        {warnings.length ? <ul className="mt-3 grid gap-1.5">{warnings.map((w, i) => <li key={i} className={`rounded-lg border px-3 py-2 text-xs ${w.level === "red" ? "border-red-500/30 bg-red-500/10 text-red-300" : "border-amber-500/30 bg-amber-500/10 text-amber-300"}`}>{w.text}</li>)}</ul> : null}
        <p className="mt-3 text-xs text-slate-400">Starter grant: {n(eco.starter.tokens)} tokens per new account, up to {usd(eco.starter.worstUsd)} of AI. One-off top-up of $10: {n(eco.topup.tokens)} tokens, margin after fees {eco.topup.marginAfterFeesPct.toFixed(0)}%. Real margins from actual payments are on <Link className="underline" href="/admin/cyrus/cost">Cost</Link>.</p>
      </Section>

      <Section title="What a plan buys" sub="Typical builds per month at the plan's tokens, using the MEDIAN cost of a succeeded build in the last 30 days per model (fewer than 5 measured builds: the documented fallback, marked).">
        <TableWrap>
          <table className="w-full text-sm">
            <thead><tr className={thCls}><th>Plan</th><th>Model</th><th className="text-right">Median AI cost</th><th>Source</th><th className="text-right">Tokens per build</th><th className="text-right">Builds per month</th></tr></thead>
            <tbody>
              {eco.plans.flatMap((p) => p.builds.map((b, i) => (
                <tr key={`${p.tier}-${b.model}`} className={tdRow}>
                  <td>{i === 0 ? p.label : ""}</td>
                  <td>{modelName(b.model)}</td>
                  <td className="text-right tabular-nums">{usd(b.medianUsd, 3)}</td>
                  <td><Badge tone={b.source === "measured" ? "green" : "slate"}>{b.source === "measured" ? `measured (${costs[b.model].n})` : `fallback (${costs[b.model].n} measured)`}</Badge></td>
                  <td className="text-right tabular-nums">{n(b.tokensPerBuild)}</td>
                  <td className="text-right tabular-nums">{n(b.buildsPerPeriod)}</td>
                </tr>
              )))}
            </tbody>
          </table>
        </TableWrap>
      </Section>

      <Section title="Pricing and margin controls" sub="Edit a value to see what it does to every plan before saving. Each Save writes one setting through the audited settings action. Warnings never block a save.">
        <EconomyControls stored={stored} rows={rows} costs={costs} canSet={canSet} back="/admin/cyrus/economy" />
        <p className="mt-3 text-xs text-slate-500">Spend caps (which do refuse builds) stay on <Link className="underline" href="/admin/cyrus/cost">Cost</Link>; the two alert thresholds above only flag.</p>
      </Section>

      <Section title="Measured AI spend" sub="Last 30 days, from ModBuild.costUsd (what the build service measured).">
        {builds.length === 0 ? <Empty>No builds in the last 30 days.</Empty> : (
          <div className="grid gap-5 lg:grid-cols-2">
            <div>
              <h3 className="mb-2 text-xs font-medium text-slate-500">Per day (UTC)</h3>
              <svg viewBox="0 0 600 120" className="h-auto w-full" role="img" aria-label="AI spend per day">
                {days.map((d, i) => { const h = (d.usd / maxDay) * 100; return <g key={d.day}><title>{`${d.day}: ${usd(d.usd)} · ${d.builds} builds`}</title><rect x={i * 20 + 2} y={110 - h} width="16" height={Math.max(h, d.usd > 0 ? 1 : 0)} rx="2" fill="var(--adm-blue, #3b6be8)" /></g>; })}
                <line x1="0" x2="600" y1="110" y2="110" stroke="currentColor" strokeOpacity="0.15" />
              </svg>
              <p className="text-xs text-slate-500">Peak day {usd(maxDay)}; {days[0]?.day} to {days[days.length - 1]?.day}.</p>
            </div>
            <div>
              <h3 className="mb-2 text-xs font-medium text-slate-500">Per underlying model</h3>
              {models.length === 0 ? <p className="text-sm text-slate-400">No per-call records yet.</p> : (
                <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Model</th><th className="text-right">Calls</th><th className="text-right">Cost</th></tr></thead>
                  <tbody>{models.slice(0, 10).map((m) => <tr key={m.model} className={tdRow}><td className="break-all">{m.model}</td><td className="text-right tabular-nums">{n(m.calls)}</td><td className="text-right tabular-nums">{usd(m.costUsd)}{m.unpriced ? <span className="text-xs text-slate-500"> (+{m.unpriced} unpriced)</span> : null}</td></tr>)}</tbody></table></TableWrap>
              )}
            </div>
            <div className="lg:col-span-2">
              <h3 className="mb-2 text-xs font-medium text-slate-500">Top accounts (30 days)</h3>
              <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Account</th><th className="text-right">24 h</th><th className="text-right">7 d</th><th className="text-right">30 d</th><th className="text-right">Builds</th></tr></thead>
                <tbody>{users.map((u) => <tr key={u.userId} className={tdRow}><td className="max-w-[260px] truncate"><UserLink id={u.userId} email={emails.get(u.userId)} /></td><td className="text-right tabular-nums">{usd(u.d1)}</td><td className="text-right tabular-nums">{usd(u.d7)}</td><td className="text-right tabular-nums">{usd(u.d30)}</td><td className="text-right tabular-nums">{n(u.builds30)}</td></tr>)}</tbody></table></TableWrap>
            </div>
          </div>
        )}
      </Section>

      <Section title="Anthropic live costs" sub="What Anthropic itself billed (Admin API cost report, cached 5 minutes), next to what the builds measured. The key stays on the server.">
        <div className="grid gap-3 sm:grid-cols-3">
          <StatCard label="Measured from builds (30 d)" value={usd(total30)} delta="always shown" />
          {anthropic.state === "ok" ? (
            <>
              <StatCard label="Billed by Anthropic (30 d)" value={usd(anthropic.report.totalUsd)} delta={`${anthropic.report.from} to ${anthropic.report.to}`} />
              <StatCard label="Difference" value={usd(anthropic.report.totalUsd - total30)} delta={anthropic.report.totalUsd > 0 ? `${Math.round((total30 / anthropic.report.totalUsd) * 100)}% of the bill is in builds` : "no billed spend"} />
            </>
          ) : null}
        </div>
        {anthropic.state === "not_configured" ? (
          <p className="mt-3 rounded-lg border border-dashed border-white/10 px-3 py-3 text-sm text-slate-400" data-empty>Not configured. Set <code>ANTHROPIC_ADMIN_API_KEY</code> (an Admin API key, <code>sk-ant-admin...</code>) in the portal&apos;s server environment to pull Anthropic&apos;s own cost report here. Until then only the measured-from-builds numbers are shown.</p>
        ) : anthropic.state === "error" ? (
          <p role="alert" className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">Live pull failed: {anthropic.message} The measured numbers above are unaffected.</p>
        ) : (
          <div className="mt-3 grid gap-5 lg:grid-cols-2">
            <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Model (billed)</th><th className="text-right">USD</th></tr></thead>
              <tbody>{anthropic.report.byModel.slice(0, 12).map((m) => <tr key={m.model} className={tdRow}><td className="break-all">{m.model}</td><td className="text-right tabular-nums">{usd(m.usd)}</td></tr>)}</tbody></table></TableWrap>
            <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Day</th><th className="text-right">Billed</th></tr></thead>
              <tbody>{anthropic.report.days.slice(-10).reverse().map((d) => <tr key={d.day} className={tdRow}><td>{d.day}</td><td className="text-right tabular-nums">{usd(d.usd)}</td></tr>)}</tbody></table></TableWrap>
            <p className="text-xs text-slate-500 lg:col-span-2">Fetched {anthropic.fetchedAt.slice(11, 16)} UTC. The organisation may bill other products too, so a gap is not necessarily a leak.</p>
          </div>
        )}
      </Section>
    </div>
  );
}
