import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { ECON_DEFAULTS, FALLBACK_BUILD_COST_USD, medianCostByModel, parseEconFees, planEconomics, previewEconomics, spendByDay, starterCost, topupMargin } from "../lib/cyrus/admin/economy";
import { parseTokenConfig } from "../lib/cyrus/tokens/config";
import { ANTHROPIC_COST_TTL_MS, clearAnthropicCostCache, getAnthropicCosts, parseCostReport, pullCostReport, type FetchLike } from "../lib/cyrus/admin/anthropic-cost";
import { validateSettingValue } from "../lib/cyrus/admin/settings-catalog";
import { CYRUS_ADMIN_TABS } from "../lib/cyrus/admin/perms";

const cfg = parseTokenConfig({});
const fees = parseEconFees({});
const none = medianCostByModel([]);

describe("cyrus admin economy: projection", () => {
  it("fees default to Stripe's 2.9% + 30c and are editable settings", () => {
    assert.deepEqual(fees, ECON_DEFAULTS);
    assert.equal(parseEconFees({ cyrus_econ_stripe_pct: "3.5", cyrus_econ_stripe_fixed_cents: "25" }).stripePct, 3.5);
    assert.equal(parseEconFees({ cyrus_econ_stripe_pct: "junk" }).stripePct, 2.9);
    assert.equal(validateSettingValue("cyrus_econ_stripe_pct", "3.1").ok, true);
    assert.equal(validateSettingValue("cyrus_econ_stripe_pct", "99").ok, false);
  });
  it("uses the documented fallback until 5 builds are measured, then the median", () => {
    assert.equal(none.katara.source, "fallback");
    assert.equal(none.katara.medianUsd, FALLBACK_BUILD_COST_USD.katara);
    const four = Array.from({ length: 4 }, () => ({ model: "saka", costUsd: 1, succeeded: true }));
    assert.equal(medianCostByModel(four).saka.source, "fallback");
    const m = medianCostByModel([...four, { model: "saka", costUsd: 3, succeeded: true }, { model: "saka", costUsd: 99, succeeded: false }, { model: "saka", costUsd: 0, succeeded: true }]);
    assert.equal(m.saka.source, "measured");
    assert.equal(m.saka.n, 5);
    assert.equal(m.saka.medianUsd, 1);
  });
  it("computes budget, worst case and margins before and after fees from the config", () => {
    const [kat, saka, all] = planEconomics({ cfg, fees, costs: none });
    // Katara: $4.99, 750 tokens at 500/USD = $1.50 budget, multiplier 1
    assert.equal(kat.budgetUsd, 1.5);
    assert.equal(kat.worstCostUsd, 1.5);
    assert.equal(kat.stripeFeeUsd, 0.44); // 4.99 * 2.9% + 0.30
    assert.equal(kat.marginBeforeFeesUsd, 3.49);
    assert.equal(kat.marginAfterFeesUsd, 3.05);
    assert.ok(Math.abs(kat.marginAfterFeesPct - (3.05 / 4.99) * 100) < 0.01);
    // Saka unlocks Katara + Saka (both x1): 3500 tokens = $7.00
    assert.equal(saka.worstCostUsd, 7);
    // All: 10000 tokens, cheapest multiplier is 1 (Katara), so worst case $20
    assert.equal(all.worstCostUsd, 20);
    // builds per month on Katara: 750 / (0.09 * 500 * 1 = 45 tokens) = 16
    assert.equal(kat.builds[0].model, "katara");
    assert.equal(kat.builds[0].tokensPerBuild, 45);
    assert.equal(kat.builds[0].buildsPerPeriod, 16);
    // Yakko build: 0.55 * 500 * 1.25 = 344 tokens
    assert.equal(all.builds[0].model, "yakko");
    assert.equal(all.builds[0].tokensPerBuild, 344);
  });
  it("warns (never blocks) below the margin line and when negative", () => {
    const thin = planEconomics({ cfg: parseTokenConfig({ cyrus_tok_plan_katara_tokens: "1500" }), fees, costs: none })[0];
    assert.equal(thin.warnings[0].level, "amber"); // $4.99 - $3.00 - $0.44 = 1.55 = 31%
    const neg = planEconomics({ cfg: parseTokenConfig({ cyrus_tok_plan_katara_tokens: "5000" }), fees, costs: none })[0];
    assert.equal(neg.warnings[0].level, "red");
    assert.ok(neg.marginAfterFeesUsd < 0);
    const ok = planEconomics({ cfg, fees, costs: none });
    assert.deepEqual(ok.flatMap((p) => p.warnings.filter((w) => w.code !== "mult_order")), []);
  });
  it("preview merges an unsaved draft over the stored values without changing them", () => {
    const stored = { cyrus_tok_tokens_per_usd: "500" };
    const p = previewEconomics(stored, { cyrus_tok_tokens_per_usd: "250" }, none);
    assert.equal(p.plans[0].worstCostUsd, 3); // 750 / 250
    assert.equal(previewEconomics(stored, {}, none).plans[0].worstCostUsd, 1.5);
    assert.equal(stored.cyrus_tok_tokens_per_usd, "500");
  });
  it("starter and top-up costs", () => {
    assert.deepEqual(starterCost(cfg), { tokens: 70, worstUsd: 0.14 });
