  });
  it("Economy is a billing-area tab", () => {
    assert.ok(CYRUS_ADMIN_TABS.some((t) => t.id === "economy" && t.area === "billing"));
  });
});

const page = (amounts: [string, string][], more = false) => ({ data: [{ starting_at: "2026-10-12T00:00:00Z", ending_at: "2026-10-13T00:00:00Z", results: amounts.map(([model, amount]) => ({ amount, currency: "USD", model })) }], has_more: more, next_page: more ? "page_2" : null });

