#!/usr/bin/env node
// cyrus.my landing: the "Featured mods" section, generated into dist/index.html at build time (plain Node, no deps).
//   node featured.mjs --in dist/index.html --json <file|https-url> [--out <file>] [--origin https://nxeon.cloud]
// The JSON is the public list the app serves at /api/cyrus/featured ({ cards: [...] }, public + moderated mods only).
// The section replaces whatever sits between the markers in the page; an empty list or an unreadable source leaves the
// markers EMPTY (the section simply is not there). Every value is HTML-escaped; links are built here, never taken from data.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const START = "<!-- featured-mods:start -->";
export const END = "<!-- featured-mods:end -->";
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const slugOk = (s) => typeof s === "string" && /^[a-z0-9][a-z0-9-]{0,80}$/.test(s);

const CSS = `<style>
#featured .fm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
#featured .fm-card{display:flex;flex-direction:column;gap:12px;padding:20px;border:1px solid var(--line-2);border-radius:var(--r);background:var(--glass)}
#featured .fm-card h3{margin:0;font-size:18px;line-height:1.25}
#featured .fm-by,#featured .fm-meta{margin:0;color:var(--ink-3);font-size:13px}
#featured .fm-tag{margin:0;color:var(--ink-2);font-size:14.5px}
#featured .fm-foot{margin-top:auto;display:flex;flex-wrap:wrap;align-items:center;gap:12px}
#featured .fm-rate{color:var(--ink-2);font-size:13px}
#featured .fm-foot .btn{margin-left:auto}
@media (max-width:560px){#featured .fm-grid{grid-template-columns:1fr}}
</style>`;

/** The section HTML for a list of public cards ("" for none). */
export function renderFeaturedSection(cards, { origin = "https://nxeon.cloud", makeBase = "/new" } = {}) {
  const list = (Array.isArray(cards) ? cards : []).filter((c) => c && slugOk(c.slug) && typeof c.title === "string" && c.title.trim()).slice(0, 12);
