import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { FEATURED_MAX, isFeaturable, makeLikeHref, parseFeatured, setFeatured } from "../lib/cyrus-mods/featured";
// @ts-expect-error plain ESM script, no types
import { applyFeatured, renderFeaturedSection, START, END } from "../apps/cyrus-site/featured.mjs";
import { canCyrusAdmin } from "../lib/cyrus/admin/perms";

describe("featured mods: the list", () => {
  it("parses defensively and dedupes", () => {
    assert.deepEqual(parseFeatured('["a","b","a",3,"../x"]'), ["a", "b"]);
    assert.deepEqual(parseFeatured("not json"), []);
    assert.deepEqual(parseFeatured(null), []);
    assert.equal(parseFeatured(JSON.stringify(Array.from({ length: 30 }, (_, i) => `p${i}`))).length, FEATURED_MAX);
  });
  it("feature appends, unfeature removes, the cap is explicit", () => {
    const a = setFeatured([], "p1", true);
    assert.deepEqual(a, { ok: true, list: ["p1"] });
    assert.deepEqual(setFeatured(["p1", "p2"], "p1", false), { ok: true, list: ["p2"] });
    assert.deepEqual(setFeatured(["p1"], "p1", true), { ok: true, list: ["p1"] });
    const full = Array.from({ length: FEATURED_MAX }, (_, i) => `p${i}`);
    assert.equal(setFeatured(full, "new", true).ok, false);
  });
  it("only public, not taken down pages are featurable", () => {
    assert.ok(isFeaturable({ visibility: "PUBLIC", hiddenAt: null }));
    assert.ok(!isFeaturable({ visibility: "PRIVATE", hiddenAt: null }));
    assert.ok(!isFeaturable({ visibility: "PUBLIC", hiddenAt: new Date() }));
  });
  it("support staff may feature (moderation role), billing may not", () => {
    assert.ok(canCyrusAdmin("SUPPORT", "mods.feature"));
    assert.ok(!canCyrusAdmin("BILLING", "mods.feature"));
  });
  it("the make-like link carries the slug", () => {
    assert.equal(makeLikeHref("my-mod"), "/dashboard/cyrus/app/new?like=my-mod");
    assert.equal(makeLikeHref("a b", "/new"), "/new?like=a%20b");
  });
});

describe("featured mods: landing section", () => {
  const card = { slug: "vein-miner", title: "Vein <Miner>", tagline: "Mine whole veins", creator: "Sam", game: "Minecraft", gameVersion: "1.21.11", version: "1.2.0", rating: 4.5, ratings: 8 };
  it("renders name, game/version, author, rating and the CTA, escaped", () => {
    const h = renderFeaturedSection([card]);
    assert.match(h, /Vein &lt;Miner&gt;/);
    assert.match(h, /Minecraft · 1\.21\.11 · v1\.2\.0/);
    assert.match(h, /by Sam/);
    assert.match(h, /4\.5 \/ 5 \(8\)/);
    assert.match(h, /href="\/new\?like=vein-miner">Make something like this/);
    assert.match(h, /https:\/\/nxeon\.cloud\/mods\/cyrus\/vein-miner/);
  });
  it("empty or invalid input renders nothing and leaves the markers empty", () => {
    assert.equal(renderFeaturedSection([]), "");
    assert.equal(renderFeaturedSection([{ slug: "../x", title: "t" }, { slug: "ok", title: "" }]), "");
    const page = `a\n${START}\nOLD\n${END}\nb`;
    assert.equal(applyFeatured(page, ""), `a\n${START}\n${END}\nb`);
    assert.ok(applyFeatured(page, "<section/>").includes("<section/>"));
    assert.ok(!applyFeatured(page, "<section/>").includes("OLD"));
    assert.equal(applyFeatured("no markers", "<s/>"), "no markers");
  });
});
EOF
