import { NextResponse } from "next/server";
import { syncBuild, toView } from "@/lib/modbuilder/store";
import { NOT_FOUND, ownedBuild } from "../../_lib";

export const dynamic = "force-dynamic";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  let row = o.build;
  try { row = await syncBuild(row); } catch (e) { console.error("[modbuilder] sync", row.id, (e as Error).message); }
  return NextResponse.json({ build: toView(row) }, { headers: { "Cache-Control": "no-store" } });
}

/** One project (r39): its builds with Test Flight, engine revisions, install + rollback, and links into the studios. */
export default async function CyrusProjectPage({ params, searchParams }: { params: Promise<{ rootId: string }>; searchParams: Promise<{ server?: string | string[] }> }) {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  const { rootId } = await params;
  const want = (await searchParams).server; const initialServer = typeof want === "string" ? want : null;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(rootId)) notFound();
  // ownership: only this user's builds of this chain; a stranger's id is the same 404 as a missing one
  const rows = await cyrusDb.modBuild.findMany({ where: { userId: v.user.id, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" }, take: 200 });
  if (!rows.some((r) => r.id === rootId)) notFound();
  const project = groupProjects(rows.map(toView)).find((p) => p.rootId === rootId);
  if (!project) notFound();
  const now = new Date();
