// Portals branch (2026-10-13): host routing for the new surfaces + the simple customer view's wiring.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { bridgeConfig } from "../lib/cyrus/bridge/config";
import { cyrusAdminHostRoute, cyrusHostRoute, isCyrusAdminPath } from "../lib/cyrus/bridge/routing";

const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", CYRUS_HOSTS: "cyrus.my,www.cyrus.my", APP_URL: "https://nxeon.cloud" });
const host = (pathname: string, search = "", method = "GET") => cyrusHostRoute({ pathname, search, method, cfg });
const admin = (pathname: string, method = "GET") => cyrusAdminHostRoute({ pathname, search: "", method });

describe("cyrus.my host: new surfaces", () => {
  it("the featured API is reachable (same prefix as the other Cyrus APIs)", () => {
    assert.deepEqual(host("/api/cyrus/featured"), { kind: "pass" });
  });
  it("'Make something like this' lands on the customer app's New mod page", () => {
    assert.deepEqual(host("/new", "?like=vein-miner"), { kind: "rewrite", pathname: "/dashboard/cyrus/app/new" });
  });
  it("community pages are NOT served on cyrus.my (the landing links to nxeon.cloud for them)", () => {
    assert.deepEqual(host("/mods/cyrus"), { kind: "notfound" });
    assert.deepEqual(host("/mods/cyrus/some-mod"), { kind: "notfound" });
  });
  it("the Simple / Studio switch targets exist: /home (app) and /studio (rewritten to the studio)", () => {
    assert.equal(host("/home").kind, "rewrite");
    assert.deepEqual(host("/studio"), { kind: "rewrite", pathname: "/dashboard/cyrus" });
  });
});

describe("secret admin host: Live and Economy", () => {
  it("both tabs and their APIs pass; other paths stay 404", () => {
    for (const p of ["/admin/cyrus/live", "/admin/cyrus/economy", "/api/admin/cyrus/live", "/admin/cyrus/community"]) assert.deepEqual(admin(p), { kind: "pass" }, p);
    assert.deepEqual(admin("/admin/users"), { kind: "notfound" });
    assert.deepEqual(admin("/mods/cyrus"), { kind: "notfound" });
  });
  it("with ADMIN_HOST_ONLY the new paths are 404 on other hosts too", () => {
    assert.ok(isCyrusAdminPath("/admin/cyrus/live"));
    assert.ok(isCyrusAdminPath("/api/admin/cyrus/live"));
    assert.ok(isCyrusAdminPath("/admin/cyrus/economy"));
  });
});

describe("simple customer view wiring", () => {
  const read = (p: string) => readFileSync(new URL(`../${p}`, import.meta.url), "utf8");
  it("every app page carries the Simple / Studio switch", () => {
    const l = read("app/dashboard/cyrus/app/layout.tsx");
    assert.match(l, /aria-label="View"/);
    assert.match(l, />Simple</);
    assert.match(l, />Studio</);
  });
  it("a running build is followed on the project page and says what it is doing in plain words", () => {
    assert.match(read("app/dashboard/cyrus/app/projects/[rootId]/page.tsx"), /<BuildFollower/);
    const f = read("components/cyrus/app/BuildFollower.tsx");
    assert.match(f, /router\.refresh\(\)/);
    assert.match(f, /Writing the code\./);
  });
  it("new mod: one prompt first, options collapsed, coach questions shown, nothing blocked by them", () => {
    const n = read("components/cyrus/app/NewModFlow.tsx");
    assert.match(n, /const \[advanced, setAdvanced\] = useState\(false\)/);
    assert.match(n, /A few details would help/);
    assert.match(n, /Optional\. You can build without them\./);
  });
});
EOF
timeout 600 /opt/nxeon/scripts/devhost test test/cyrus-portals-routing.test.ts 2>&1 | grep -E "^# (pass|fail)|not ok|expected|actual" | head

